    ('1404','GENARO GRAVE HERNANDEZ','GT-TSE-CME-2023-1404','{"year":2023,"total":11,"titular_total":8,"substitute_total":3,"groups":[{"party":"VAMOS","seats":5},{"party":"CABAL","seats":2},{"party":"TODOS","seats":1}],"members":[{"office":"ALCALDE","name":"GENARO GRAVE HERNANDEZ","party":"VAMOS","source_page":2,"source_office_text":null},{"office":"CONCEJAL 1","name":"FRANCISCO COJ RUIZ","party":"VAMOS","source_page":2,"source_office_text":"CONCEJAL PRIMERO"},{"office":"CONCEJAL 2","name":"CARLOS ENRIQUE CUX BENITO","party":"VAMOS","source_page":2,"source_office_text":"NJ) CONCEJAL SEGUNDO"},{"office":"CONCEJAL 3","name":"ROLANDO GUTIERREZ GUTIERREZ","party":"CABAL","source_page":2,"source_office_text":"Ñ CONCEJAL TERCERO"},{"office":"CONCEJAL 4","name":"DOMIGNO GUTIERREZ MENDEZ","party":"CABAL","source_page":2,"source_office_text":"CONCEJAL CUARTO"},{"office":"CONCEJAL 5","name":"FREDY OSCAR LEE ARGUETA MERIDA RAL DEP","party":"TODOS","source_page":2,"source_office_text":"CONCEJAL QUINTO"},{"office":"CONCEJAL SUPLENTE 1","name":"VALERIANO MORENTE GARCIA ÍA","party":"VAMOS","source_page":2,"source_office_text":"PRIMER CONCEJAL SUPLENTE"},{"office":"CONCEJAL SUPLENTE 2","name":"PEDRO ARDONIS CHIC","party":"CABAL","source_page":3,"source_office_text":"SEGUNDO CONCEJAL SUPLENTE"},{"office":"SÍNDICO 1","name":"CARLOS BARRERA MORENTE","party":"VAMOS","source_page":1,"source_office_text":"PRIMERO Y SEGUNDO"},{"office":"SÍNDICO 2","name":"MARIANO COJ GARCIA","party":"VAMOS","source_page":1,"source_office_text":"PRIMERO Y SEGUNDO"},{"office":"SÍNDICO SUPLENTE","name":"PEDRO TZOC PANJOJ","party":"VAMOS","source_page":null,"source_office_text":"SÍNDICO SUPLENTE"}],"mayor":"GENARO GRAVE HERNANDEZ","winner_party":"VAMOS","detail_status":"FULL_MEMBERS_OFFICIAL_AGREEMENT","warnings":[],"source_id":"GT-TSE-CME-2023-1404","source_url":"https://tse.org.gt/images/ss/cme/qui_08-2023.pdf","source_page_url":"https://tse.org.gt/comunicacion/publicaciones/corporaciones-municipales-electas-2023/corporacion-quiche","agreement_number":8,"applied_amendments":[]}'::jsonb,'[]'::jsonb),
