name":"JACINTO BRITO RAMIREZ","party":"Coalición Valor-Unionista","source_page":1,"source_office_text":"PRIMERO Y SEGUNDO"},{"office":"SÍNDICO SUPLENTE","name":"JUAN SANCHEZ SANCHEZ","party":"Coalición Valor-Unionista","source_page":null,"source_office_text":"SÍNDICO SUPLENTE"}],"mayor":"GREGORIO BENJAMIN SOTO BARRIOS","winner_party":"Coalición Valor-Unionista","detail_status":"FULL_MEMBERS_OFFICIAL_AGREEMENT","warnings":[],"source_id":"GT-TSE-CME-2023-1405","source_url":"https://tse.org.gt/images/ss/cme/qui_09-2023.pdf","source_page_url":"https://tse.org.gt/comunicacion/publicaciones/corporaciones-municipales-electas-2023/corporacion-quiche","agreement_number":9,"applied_amendments":[]}'::jsonb,'[]'::jsonb)
), targets as (
  select p.id, p.profile, p.source_manifest, i.*
  from incoming i
  join public.municipalities m
    on m.country_code = 'GT'
   and m.municipality_code = i.municipality_code
  join data_vault.municipality_intelligence_profiles_v1 p
    on p.municipality_id = m.id
), patched as (
  select
    id,
    source_id,
    amendments,
    jsonb_set(
      jsonb_set(
        profile,
        '{electoral_history,councils}',
        coalesce((
          select jsonb_agg(council_item order by (council_item->>'year')::integer)
          from jsonb_array_elements(coalesce(profile->'electoral_history'->'councils', '[]'::jsonb)) council_item
          where (council_item->>'year')::integer <> 2023
        ), '[]'::jsonb) || jsonb_build_array(council),
        true
      ),
      '{electoral_history,elections}',
      coalesce((
        select jsonb_agg(
          case when (election->>'year')::integer = 2023 then
            jsonb_set(
              jsonb_set(election, '{winner_candidate}', to_jsonb(mayor), true),
              '{results}',
              coalesce((
                select jsonb_agg(
                  case when (result->>'rank')::integer = 1
                    then jsonb_set(result, '{candidate}', to_jsonb(mayor), true)
                    else result
                  end
                  order by (result->>'rank')::integer
                )
                from jsonb_array_elements(coalesce(election->'results', '[]'::jsonb)) result
              ), '[]'::jsonb),
              true
            )
          else election end
          order by (election->>'year')::integer
        )
        from jsonb_array_elements(coalesce(profile->'electoral_history'->'elections', '[]'::jsonb)) election
      ), '[]'::jsonb),
      true
    ) as profile
  from targets
)
update data_vault.municipality_intelligence_profiles_v1 p
set
  profile = jsonb_set(
    patched.profile,
    '{source_manifest}',
    coalesce(patched.profile->'source_manifest', '{}'::jsonb)
      || jsonb_build_object('municipal_council_2023', patched.source_id)
      || case when jsonb_array_length(patched.amendments) > 0
           then jsonb_build_object('municipal_council_2023_amendments', patched.amendments)
           else '{}'::jsonb
         end,
    true
  ),
  source_manifest = coalesce(p.source_manifest, '{}'::jsonb)
    || jsonb_build_object('municipal_council_2023', patched.source_id)
    || case when jsonb_array_length(patched.amendments) > 0
         then jsonb_build_object('municipal_council_2023_amendments', patched.amendments)
         else '{}'::jsonb
       end,
  generated_at = now(),
  updated_at = now()
from patched
where p.id = patched.id;

do $$
declare
  loaded integer;
begin
  select count(*) into loaded
  from data_vault.municipality_intelligence_profiles_v1 p
  join public.municipalities m on m.id = p.municipality_id
  where m.municipality_code in ('0904', '0905', '0906', '0907', '0908', '0909', '0910', '0911', '0912', '0913', '0914', '0915', '0916', '0917', '0918', '0919', '0920', '0921', '0922', '0923', '0924', '1001', '1002', '1003', '1004', '1005', '1006', '1007', '1008', '1009', '1010', '1011', '1012', '1013', '1014', '1015', '1016', '1017', '1018', '1019', '1020', '1021', '1101', '1102', '1103', '1104', '1105', '1106', '1107', '1108', '1109', '1201', '1202', '1203', '1204', '1205', '1206', '1207', '1208', '1209', '1210', '1211', '1212', '1213', '1214', '1215', '1216', '1217', '1218', '1219', '1220', '1221', '1222', '1223', '1224', '1225', '1226', '1227', '1228', '1229', '1230', '1301', '1302', '1303', '1304', '1305', '1306', '1307', '1308', '1309', '1310', '1311', '1312', '1313', '1314', '1315', '1316', '1317', '1318', '1319', '1320', '1321', '1322', '1323', '1324', '1325', '1326', '1327', '1328', '1329', '1330', '1331', '1332', '1333', '1401', '1402', '1403', '1404', '1405')
    and p.profile->'source_manifest' ? 'municipal_council_2023'
    and jsonb_array_length(
      coalesce(p.profile->'electoral_history'->'councils', '[]'::jsonb)
    ) = 4;
  if loaded <> 119 then
    raise exception 'TSE 2023 corporation part 02: expected 119, loaded %', loaded;
  end if;
end $$;

commit;

